  }\

  var graficaDona = generarGraficaDonaSemanal(d.distribucionSemana || [], gastoTotalSemana);

  return '<!DOCTYPE html>\\n<html lang="es">\\n<head>\\n<meta charset="UTF-8">\\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\\n<title>Reporte Semanal de Gastos - Royal Express C.A.</title>\\n<style>\\n' +\
    '  :root { --bg: #0f172a; --bg-card: #161f36; --border: #23304f; --text-primary: #e5e9f5; --text-secondary: #93a0c2; --accent: #38bdf8; }\\n' +\
