function generarReporteSeguimiento() {
  var seccion1Cards = d.categorias.map(function(c) {
    var pctSemana = c.limiteSemanal > 0 ? Math.min(100, Math.max(0, ((c.limiteSemanal - c.disponibleSemana) / c.limiteSemanal) * 100)) : 0;
    var est = colorEstado(pctSemana);
    var disponibleTxt = c.disponibleSemana >= 0 ? formatUSD(c.disponibleSemana) : formatUSD(Math.abs(c.disponibleSemana)) + ' excedido';
    return '<div class="card"><div class="card-head"><span class="card-title">' + c.emoji + ' ' + c.nombre + '</span><span class="pill" style="color:' + est.color + '; background:' + est.bg + ';">' + disponibleTxt + '</span></div><div class="card-row"><span>Límite semanal</span><span class="value">' + formatUSD(c.limiteSemanal) + '</span></div>' + barra(pctSemana, est.color) + '<div class="card-footer"><span>Consumo de la semana en curso: ' + formatUSD(c.gastoSemana) + '</span></div></div>';
  }).join('\n');

  var seccion2Cards = d.categorias.map(function(c) {
    var est = colorEstado(c.porcentajeMensual);
    return '<div class="card"><div class="card-head"><span class="card-title">' + c.emoji + ' ' + c.nombre + '</span><span class="pill" style="color:' + est.color + '; background:' + est.bg + ';">' + est.label + '</span></div><div class="card-row"><span>Ejecutado</span><span class="value">' + formatUSD(c.gastoMensual) + ' / ' + formatUSD(c.limiteMensual) + '</span></div>' + barra(c.porcentajeMensual, est.color) + '<div class="card-footer"><span>' + c.porcentajeMensual + '% del límite mensual</span></div></div>';
  }).join('\n');

  var estadoGlobal = colorEstado(d.porcentajeGlobalMensual);

  function generarGraficaLineas(etiquetas, series) {
    var W = 900, H = 420;
    var padL = 70, padR = 24, padT = 24, padB = 54;
    var plotW = W - padL - padR;
    var plotH = H - padT - padB;
    var n = etiquetas.length;
    var maxVal = 0;
    series.forEach(function(s) { s.valores.forEach(function(v) { if (v > maxVal) maxVal = v; }); });
    if (maxVal <= 0) maxVal = 1;
    var pasos = 4;
    var raw = maxVal / pasos;
    var mag = Math.pow(10, Math.floor(Math.log10(raw)));
    var norm = raw / mag;
    var step;
    if (norm <= 1) step = 1 * mag;
    else if (norm <= 2) step = 2 * mag;
    else if (norm <= 5) step = 5 * mag;
    else step = 10 * mag;
    var techo = step * pasos;
    var xFor = function(i) { return padL + (n <= 1 ? plotW / 2 : (plotW * i) / (n - 1)); };
    var yFor = function(v) { return padT + plotH - (v / techo) * plotH; };
    var grid = '';
    for (var g = 0; g <= pasos; g++) {
      var val = step * g;
      var y = yFor(val);
      grid += '<line x1="' + padL + '" y1="' + y.toFixed(1) + '" x2="' + (W - padR).toFixed(1) + '" y2="' + y.toFixed(1) + '" stroke="#23304f" stroke-width="1"/>';
      grid += '<text x="' + (padL - 10).toFixed(1) + '" y="' + (y + 4).toFixed(1) + '" fill="#93a0c2" font-size="13" text-anchor="end">' + formatNum(val).replace(',00','') + '</text>';
    }
    var ejeX = '';
    etiquetas.forEach(function(et, i) {
      ejeX += '<text x="' + xFor(i).toFixed(1) + '" y="' + (H - padB + 24).toFixed(1) + '" fill="#93a0c2" font-size="13" text-anchor="middle">' + et + '</text>';
    });
    var lineas = '';
    series.forEach(function(s) {
      if (!s.valores || !s.valores.length) return;
      var pts = s.valores.map(function(v, i) { return xFor(i).toFixed(1) + ',' + yFor(v).toFixed(1); }).join(' ');
      lineas += '<polyline points="' + pts + '" fill="none" stroke="' + s.color + '" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>';
      s.valores.forEach(function(v, i) {
        lineas += '<circle cx="' + xFor(i).toFixed(1) + '" cy="' + yFor(v).toFixed(1) + '" r="3.5" fill="' + s.color + '"/>';
      });
    });
    var svg = '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Evolución semanal por categoría">' + grid + ejeX + lineas + '</svg>';
    var leyenda = series.map(function(s) {
      return '<span class="legend-item"><span class="legend-dot" style="background:' + s.color + ';"></span>' + s.nombre + '</span>';
    }).join('');
    return svg + '<div class="legend">' + leyenda + '</div>';
  }

  function generarGraficaDona(distribucion, totalMes) {
    var size = 260, cx = size / 2, cy = size / 2;
    var r = 95, grosor = 34;
    var circ = 2 * Math.PI * r;
    var offset = 0;
