      offset += len;
    });
    var svg = '<svg viewBox="0 0 ' + size + ' ' + size + '" width="220" height="220" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Distribución de gastos por categoría"><circle cx="' + cx + '" cy="' + cy + '" r="' + r + '" fill="none" stroke="#0a1224" stroke-width="' + grosor + '"/>' + segmentos + '<text x="' + cx + '" y="' + (cy - 6) + '" fill="#93a0c2" font-size="12" text-anchor="middle">Total mes</text><text x="' + cx + '" y="' + (cy + 16) + '" fill="#e5e9f5" font-size="17" font-weight="700" text-anchor="middle">' + formatNum(totalMes) + '</text></svg>';
    var filas = distribucion.map(function(seg) {
      return '<div class="dona-row"><span class="dona-label"><span class="legend-dot" style="background:' + seg.color + ';"></span>' + seg.emoji + ' ' + seg.nombre + '</span><span class="dona-pct">' + seg.porcentaje + '%</span></div>';
    }).join('');
    return '<div class="dona-wrap"><div class="dona-svg">' + svg + '</div><div class="dona-list">' + filas + '</div></div>';
  }

  var graficaLineas = generarGraficaLineas(d.etiquetasSemanas || [], d.seriesEvolucion || []);
  var graficaDona = generarGraficaDona(d.distribucion || [], d.gastoTotalGlobalMes || 0);

  return '<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">\n<title>Reporte Visual - Royal Express C.A.</title>\n<style>\n' +
    '  :root { --bg: #0f172a; --bg-card: #161f36; --border: #23304f; --text-primary: #e5e9f5; --text-secondary: #93a0c2; --accent: #38bdf8; }\n' +
    '  * { box-sizing: border-box; margin: 0; padding: 0; }\n' +
    '  body { background: var(--bg); color: var(--text-primary); font-family: \'Segoe UI\', -apple-system, BlinkMacSystemFont, Roboto, Arial, sans-serif; padding: 32px 20px 64px; }\n' +
    '  .container { max-width: 960px; margin: 0 auto; }\n' +
    '  header { text-align: center; margin-bottom: 36px; padding-bottom: 24px; border-bottom: 1px solid var(--border); }\n' +
    '  header h1 { font-size: 24px; font-weight: 700; }\n' +
    '  header p { color: var(--text-secondary); font-size: 14px; margin-top: 6px; }\n' +
    '  .author-badge { display: inline-block; margin-top: 8px; font-size: 11px; color: var(--accent); font-family: monospace; letter-spacing: 0.5px; }\n' +
    '  .summary-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 14px; margin: 28px 0 44px; }\n' +
    '  .summary-box { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 16px 18px; }\n' +
    '  .summary-box .label { font-size: 12px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.5px; }\n' +
    '  .summary-box .val { font-size: 20px; font-weight: 700; margin-top: 6px; }\n' +
    '  section { margin-bottom: 46px; }\n' +
    '  .section-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 18px; }\n' +
    '  .section-head .num { width: 26px; height: 26px; border-radius: 50%; background: var(--accent); color: #06111f; display: inline-flex; align-items: center; justify-content: center; font-size: 13px; font-weight: 700; flex-shrink: 0; }\n' +
    '  .section-head h2 { font-size: 17px; font-weight: 700; }\n' +
    '  .section-desc { color: var(--text-secondary); font-size: 13px; margin: -8px 0 18px 36px; }\n' +
    '  .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 14px; }\n' +
    '  .card { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 18px; }\n' +
    '  .card-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; gap: 8px; }\n' +
    '  .card-title { font-size: 14px; font-weight: 600; }\n' +
    '  .pill { font-size: 11px; font-weight: 700; padding: 4px 9px; border-radius: 999px; white-space: nowrap; }\n' +
    '  .card-row { display: flex; justify-content: space-between; font-size: 12.5px; color: var(--text-secondary); margin-bottom: 8px; }\n' +
    '  .card-row .value { color: var(--text-primary); font-weight: 600; }\n' +
    '  .bar-track { width: 100%; height: 8px; background: #0a1224; border-radius: 999px; overflow: hidden; border: 1px solid var(--border); }\n' +
    '  .bar-fill { height: 100%; min-width: 2px; border-radius: 999px; }\n' +
    '  .card-footer { margin-top: 10px; font-size: 12px; color: var(--text-secondary); }\n' +
    '  .chart-card { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 18px; overflow-x: auto; }\n' +
    '  .chart-card svg { display: block; max-width: 100%; height: auto; }\n' +
    '  .legend { display: flex; flex-wrap: wrap; gap: 10px 16px; margin-top: 16px; justify-content: center; }\n' +
    '  .legend-item { display: inline-flex; align-items: center; gap: 6px; font-size: 12.5px; color: var(--text-secondary); }\n' +
    '  .legend-dot { width: 10px; height: 10px; border-radius: 50%; display: inline-block; flex-shrink: 0; }\n' +
    '  .dona-wrap { display: flex; flex-wrap: wrap; align-items: center; gap: 24px; justify-content: center; }\n' +
    '  .dona-list { flex: 1 1 260px; min-width: 240px; }\n' +
