function obtenerCampo(row, aliasList) {
  if (!row || typeof row !== 'object') return undefined;
  const keys = Object.keys(row);
  for (const key of keys) {
    const keyLimpia = key.trim().toUpperCase();
    for (const alias of aliasList) {
      if (keyLimpia === alias.toUpperCase()) {
        const val = row[key];
        if (val !== undefined && val !== null && val !== '') return val;
      }
    }
  }
  for (const key of keys) {
    const keyLimpia = key.trim().toUpperCase();
    for (const alias of aliasList) {
      if (alias.length > 2 && keyLimpia.includes(alias.toUpperCase())) {
        const val = row[key];
        if (val !== undefined && val !== null && val !== '') return val;
      }
    }
  }
  return undefined;
}

function detectarMapaColumnas(items) {
  const objetivos = {
    FECHA: ['FECHA', 'FECHA GASTO', 'FECHA DE GASTO'],
    TIPO: ['TIPO DE GASTO', 'TIPO GASTO'],
    MONTO: ['$']
  };
  for (const item of items) {
    const row = item.json || {};
    const keys = Object.keys(row);
    const mapaTemp = {};
    for (const key of keys) {
      const val = row[key];
      if (val === undefined || val === null || val === '') continue;
      const valLimpio = String(val).trim().toUpperCase();
      for (const campo of Object.keys(objetivos)) {
        if (mapaTemp[campo]) continue;
        if (objetivos[campo].indexOf(valLimpio) !== -1) {
          mapaTemp[campo] = key;
        }
      }
    }
    if (mapaTemp.FECHA && mapaTemp.TIPO && mapaTemp.MONTO) {
      return mapaTemp;
    }
  }
  return null;
}

function leerCampo(row, mapaColumnas, campo, aliasEstatico) {
  if (mapaColumnas && mapaColumnas[campo]) {
    const val = row[mapaColumnas[campo]];
    if (val !== undefined && val !== null && val !== '') return val;
  }
  return obtenerCampo(row, aliasEstatico);
}

function extraerMonto(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;
  if (typeof valor === 'number') return isNaN(valor) ? 0 : valor;
  let str = String(valor).trim();
  if (!str) return 0;
  let esNegativo = false;
  if (str.startsWith('(') && str.endsWith(')')) {
    esNegativo = true;
    str = str.slice(1, -1);
  }
  str = str.replace(/[^0-9.,-]/g, '');
  if (!str) return 0;
  const lastDot = str.lastIndexOf('.');
  const lastComma = str.lastIndexOf(',');
  if (lastDot !== -1 && lastComma !== -1) {
    if (lastComma > lastDot) {
      str = str.replace(/\./g, '').replace(',', '.');
    } else {
      str = str.replace(/,/g, '');
    }
  } else if (lastComma !== -1) {
    str = str.replace(',', '.');
  }
  let num = parseFloat(str);
  if (isNaN(num)) return 0;
  return esNegativo ? -num : num;
}

function parseFecha(valor) {
  if (!valor) return null;
  if (valor instanceof Date) return isNaN(valor.getTime()) ? null : valor;
  if (typeof valor === 'number') {
    if (valor > 30000 && valor < 60000) {
      const dateMs = (valor - 25569) * 86400 * 1000;
      const temp = new Date(dateMs);
      return new Date(temp.getUTCFullYear(), temp.getUTCMonth(), temp.getUTCDate());
    }
    return null;
  }
  const str = String(valor).trim();
  if (!str) return null;
  const matchDMY = str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})/);
  if (matchDMY) {
    let day = parseInt(matchDMY[1], 10);
    let month = parseInt(matchDMY[2], 10) - 1;
    let year = parseInt(matchDMY[3], 10);
    if (year < 100) year += 2000;
    if (day > 31 && year <= 31) return new Date(day, month, year);
    return new Date(year, month, day);
  }
  const parsed = new Date(str);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function normalizarCodigo(texto) {
  if (!texto) return null;
  const str = String(texto).trim().toUpperCase();
  if (str === 'G1') return 'GC1';
  if (str === 'G2') return 'GC2';
  const codigosOficiales = DEPARTAMENTOS_CONFIG.map(function(d) { return d.codigo; });
  if (codigosOficiales.includes(str)) return str;
  return null;
}

const mapaColumnas = detectarMapaColumnas(inputItems);

let mesExcel = null, anioExcel = null;
for (const item of inputItems) {
  const row = item.json || {};
  const fechaRaw = leerCampo(row, mapaColumnas, 'FECHA', ['FECHA', 'FECHA GASTO', '__EMPTY_1', 'B']);
  if (fechaRaw) {
    const fecha = parseFecha(fechaRaw);
    if (fecha && !isNaN(fecha.getTime())) {
      mesExcel = fecha.getMonth() + 1;
      anioExcel = fecha.getFullYear();
      break;
    }
  }
}
if (!mesExcel || !anioExcel) {
  const hoy = new Date();
  mesExcel = hoy.getMonth() + 1;
  anioExcel = hoy.getFullYear();
}

const NOMBRES_MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
const nombreMes = NOMBRES_MESES[mesExcel - 1];

function getDiasDelMes(year, month) { return new Date(year, month, 0).getDate(); }
function generarSemanasDelMes(year, month) {
  const diasTotales = getDiasDelMes(year, month);
  const definiciones = [{ inicio: 1, fin: 9 }, { inicio: 10, fin: 16 }, { inicio: 17, fin: 23 }, { inicio: 24, fin: diasTotales }];
  return definiciones.map(function(def) {
    return {
      inicio: new Date(year, month - 1, def.inicio, 0, 0, 0, 0),
      fin: new Date(year, month - 1, Math.min(def.fin, diasTotales), 23, 59, 59, 999)
    };
  });
}

const semanasDelMes = generarSemanasDelMes(anioExcel, mesExcel);
const totalSemanas = semanasDelMes.length;

function getUltimaFechaConGastos(items) {
  let fechaMasReciente = null;
  for (const item of items) {
    const row = item.json || {};
    const fechaRaw = leerCampo(row, mapaColumnas, 'FECHA', ['FECHA', 'FECHA GASTO', '__EMPTY_1', 'B']);
    const montoRaw = leerCampo(row, mapaColumnas, 'MONTO', ['$', 'MONTO', '__EMPTY_9', 'J']);
    const monto = extraerMonto(montoRaw);
    if (monto > 0 && fechaRaw) {
      const fecha = parseFecha(fechaRaw);
      if (fecha && !isNaN(fecha.getTime())) {
        if (!fechaMasReciente || fecha > fechaMasReciente) {
          fechaMasReciente = fecha;
        }
      }
    }
  }
  return fechaMasReciente;
}

const hoy = new Date();
const ultimaFecha = getUltimaFechaConGastos(inputItems);
const esMesActualEnEjecucion = (mesExcel === (hoy.getMonth() + 1)) && (anioExcel === hoy.getFullYear());

let periodoInicio, periodoFin, labelPeriodo;
let tituloCabecera = 'REPORTE GASTOS DIARIO';

if (executionType === 'weekly_report' && semanaNumero !== null) {
  if (semanaNumero >= 1 && semanaNumero <= totalSemanas) {
    const semana = semanasDelMes[semanaNumero - 1];
    periodoInicio = semana.inicio;
    periodoFin = semana.fin;
    tituloCabecera = 'REPORTE SEMANA ' + semanaNumero;
    const opciones = { day: '2-digit', month: '2-digit', year: 'numeric' };
    labelPeriodo = nombreMes + ' ' + anioExcel + ' | Del: ' + periodoInicio.toLocaleDateString('es-ES', opciones) + ' al ' + periodoFin.toLocaleDateString('es-ES', opciones);
  } else {
    const semanasExistentes = Array.from({ length: totalSemanas }, function(_, i) { return i + 1; });
    return [{ json: { sendNotification: true, executionType: 'weekly_report', message: '❌ <b>SEMANA NO VALIDA</b>\n\n📅 ' + nombreMes + ' ' + anioExcel + ' tiene ' + totalSemanas + ' semanas.\n\n📌 Semanas disponibles:\n' + semanasExistentes.map(function(s) { return '• /semana' + s; }).join('\n'), alertasCount: 0 } }];
  }
} else if (!esMesActualEnEjecucion) {
  periodoInicio = new Date(anioExcel, mesExcel - 1, 1, 0, 0, 0, 0);
  const ultimoDiaMes = getDiasDelMes(anioExcel, mesExcel);
  periodoFin = new Date(anioExcel, mesExcel - 1, ultimoDiaMes, 23, 59, 59, 999);
  tituloCabecera = 'REPORTE MENSUAL - ' + nombreMes.toUpperCase() + ' ' + anioExcel;
  labelPeriodo = nombreMes + ' ' + anioExcel + (Mes Completo);
} else {
  const fechaReferencia = ultimaFecha || hoy;
  let semanaActualObj = semanasDelMes[0];
  for (const sem of semanasDelMes) {
    if (fechaReferencia >= sem.inicio && fechaReferencia <= sem.fin) { semanaActualObj = sem; break; }
    else if (fechaReferencia > sem.fin) { semanaActualObj = sem; }
  }
  periodoInicio = semanaActualObj.inicio;
  periodoFin = semanaActualObj.fin;
  const opciones = { day: '2-digit', month: '2-digit', year: 'numeric' };
  labelPeriodo = nombreMes + ' ' + anioExcel + ' | Del: ' + periodoInicio.toLocaleDateString('es-ES', opciones) + ' al ' + periodoFin.toLocaleDateString('es-ES', opciones);
}

const gastosMesPorDept = {};
const gastosPeriodoPorDept = {};
DEPARTAMENTOS_CONFIG.forEach(function(d) { gastosMesPorDept[d.codigo] = 0.0; gastosPeriodoPorDept[d.codigo] = 0.0; });
let gastoTotalGlobalMes = 0.0;

const ALIAS_TIPO = ['TIPO DE GASTO', 'TIPO GASTO', 'CODIGO', 'CÓDIGO', 'DEPTO', 'DEPARTAMENTO', 'TIPO', '__EMPTY_6', '__EMPTY_3', 'G'];
const ALIAS_MONTO = ['$', 'MONTO', 'MONTO ($)', 'IMPORTE', 'GASTO', 'VALOR', 'TOTAL', '__EMPTY_9', '__EMPTY_6', 'J'];
const ALIAS_FECHA = ['FECHA', 'FECHA GASTO', 'FECHA DE GASTO', 'DIA', 'DÍA', '__EMPTY_1', 'B'];

for (const item of inputItems) {
  const row = item.json || {};
  const tipoGastoRaw = leerCampo(row, mapaColumnas, 'TIPO', ALIAS_TIPO);
  const codigo = normalizarCodigo(tipoGastoRaw);
  if (!codigo) continue;
  const montoRaw = leerCampo(row, mapaColumnas, 'MONTO', ALIAS_MONTO);
  const monto = extraerMonto(montoRaw);
  if (monto === 0) continue;
  const fechaRaw = leerCampo(row, mapaColumnas, 'FECHA', ALIAS_FECHA);
  const fechaGasto = parseFecha(fechaRaw);
  if (fechaGasto && (fechaGasto.getMonth() + 1) === mesExcel && fechaGasto.getFullYear() === anioExcel) {
    gastosMesPorDept[codigo] = (gastosMesPorDept[codigo] || 0) + monto;
    gastoTotalGlobalMes += monto;
  }
  if (fechaGasto && fechaGasto >= periodoInicio && fechaGasto <= periodoFin) {
    gastosPeriodoPorDept[codigo] = (gastosPeriodoPorDept[codigo] || 0) + monto;
  }
}

function formatUSD(val) {
  const num = Number(val); if (isNaN(num)) return 'USD 0,00';
  const rounded = Math.round(num * 100) / 100;
  let parts = rounded.toFixed(2).split('.');
  let integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return 'USD ' + integerPart + ',' + (parts[1] || '00');
}

function generarBarraProgreso(porcentaje) {
  const totalBloques = 10;
  const bloquesLlenos = Math.min(totalBloques, Math.max(0, Math.round((porcentaje / 100) * totalBloques)));
  return '█'.repeat(bloquesLlenos) + '░'.repeat(totalBloques - bloquesLlenos);
}

const deptsResumen = [];
const deptsExcedidos = [];
const deptsProximos = [];
const currentAlertState = {};

DEPARTAMENTOS_CONFIG.forEach(function(dept) {
  const codigo = dept.codigo;
