  const gastoPeriodo = gastosPeriodoPorDept[codigo] || 0;
  const gastoMensual = gastosMesPorDept[codigo] || 0;
  const limiteSemanalAprox = limiteMensual / 4;
  const porcentajePeriodo = limiteSemanalAprox > 0 ? (gastoPeriodo / limiteSemanalAprox) * 100 : 0;
  const porcentajeMensual = limiteMensual > 0 ? (gastoMensual / limiteMensual) * 100 : 0;
  deptsResumen.push({ departamento: nombre.toUpperCase(), codigo: codigo, emoji: emoji || '', gastoPeriodo: gastoPeriodo, gastoMensual: gastoMensual, limiteMensual: limiteMensual, limiteSemanalAprox: limiteSemanalAprox, porcentajePeriodo: porcentajePeriodo, porcentajeMensual: porcentajeMensual, barraPeriodo: generarBarraProgreso(porcentajePeriodo), barraMensual: generarBarraProgreso(porcentajeMensual) });

  if (executionType === 'alert_check') {
    const montoRedondeado = Math.round(gastoPeriodo * 100) / 100;
    if (porcentajePeriodo >= 100) {
      const excedido = gastoPeriodo - limiteSemanalAprox;
      deptsExcedidos.push({ nombre: nombre, codigo: codigo, emoji: emoji || '', gastoPeriodo: gastoPeriodo, limiteSemanalAprox: limiteSemanalAprox, porcentajePeriodo: porcentajePeriodo, excedido: excedido });
      currentAlertState[codigo] = montoRedondeado;
    } else if (porcentajePeriodo >= 90) {
      const disponible = limiteSemanalAprox - gastoPeriodo;
      deptsProximos.push({ nombre: nombre, codigo: codigo, emoji: emoji || '', gastoPeriodo: gastoPeriodo, limiteSemanalAprox: limiteSemanalAprox, porcentajePeriodo: porcentajePeriodo, disponible: disponible });
      currentAlertState[codigo] = montoRedondeado;
    }
  }
});

// =========================================================
// ANTI-SPAM DE ALERTAS (UMBRAL MÍNIMO DE $50.00 USD):
// Solo se alerta un departamento si es la primera vez que cruza el
// límite o si su gasto aumentó AL MENOS $50.00 USD desde la última
// vez que se alertó ESE departamento.
// =========================================================
const DIFERENCIA_MINIMA_USD = 50.00;
let hayCambioEnAlertas = false;
const nuevasAlertasDetectadas = {};

if (executionType === 'alert_check') {
  Object.keys(currentAlertState).forEach(function(cod) {
    const ultimoMontoAlertado = staticData.lastAlertedAmounts[cod];
    const montoActual = currentAlertState[cod];
    if (ultimoMontoAlertado === undefined) {
      hayCambioEnAlertas = true;
      nuevasAlertasDetectadas[cod] = montoActual;
    } else {
      const diferencia = montoActual - ultimoMontoAlertado;
      if (diferencia >= DIFERENCIA_MINIMA_USD) {
        hayCambioEnAlertas = true;
        nuevasAlertasDetectadas[cod] = montoActual;
      }
    }
  });

  // Limpiar del historial departamentos que ya volvieron a estar en rango
  Object.keys(staticData.lastAlertedAmounts).forEach(function(cod) {
    if (currentAlertState[cod] === undefined) {
      delete staticData.lastAlertedAmounts[cod];
    }
  });
}

const deptsExcedidosNotificar = deptsExcedidos.filter(function(d) { return nuevasAlertasDetectadas.hasOwnProperty(d.codigo); });
const deptsProximosNotificar = deptsProximos.filter(function(d) { return nuevasAlertasDetectadas.hasOwnProperty(d.codigo); });

if (executionType === 'alert_check') {
  const totalAlertasANotificar = deptsExcedidosNotificar.length + deptsProximosNotificar.length;

  // SI NO HAY NOVEDADES QUE SUPEREN LOS $50 USD -> SILENCIO TOTAL
  if (totalAlertasANotificar === 0 || !hayCambioEnAlertas) {
    return [{ json: { sendNotification: false, message: '' } }];
  }

  // Guardar los nuevos montos alertados
  staticData.lastAlertedAmounts = Object.assign({}, staticData.lastAlertedAmounts, nuevasAlertasDetectadas);

  let alertMsg = '🚨 <b>ROYAL EXPRESS C.A. - ALERTA DE GASTOS</b> 🚨\n\n📅 <b>Mes: ' + labelPeriodo + '</b>\n\n';
  if (deptsExcedidosNotificar.length > 0) {
    alertMsg += '🔴 <b>LIMITE EXCEDIDO</b>\nCategorias con consumo igual o mayor al limite establecido:\n\n';
    deptsExcedidosNotificar.forEach(function(d, idx) {
      let pctStr = d.porcentajePeriodo.toFixed(1).replace('.', ',') + '%';
      alertMsg += d.emoji + ' <b>' + d.nombre + '</b>\nEjecutado: ' + formatUSD(d.gastoPeriodo) + ' / Limite: ' + formatUSD(d.limiteSemanalAprox) + '\n% del limite: ' + pctStr + ' (Excedente: ' + formatUSD(d.excedido) + ')';
      if (idx < deptsExcedidosNotificar.length - 1) alertMsg += '\n\n───────────────────────\n\n';
    });
  }
  if (deptsProximosNotificar.length > 0) {
    if (deptsExcedidosNotificar.length > 0) alertMsg += '\n\n───────────────────────\n\n';
    alertMsg += '🟡 <b>PROXIMO A LIMITE</b>\nCategorias con 90% o mas de consumo (queda 10% o menos disponible):\n\n';
    deptsProximosNotificar.forEach(function(d, idx) {
      let pctStr = Math.round(d.porcentajePeriodo) + '%';
      alertMsg += d.emoji + ' <b>' + d.nombre + '</b>\nEjecutado: ' + formatUSD(d.gastoPeriodo) + ' / Limite: ' + formatUSD(d.limiteSemanalAprox) + '\n% del limite: ' + pctStr + ' (Disponible: ' + formatUSD(d.disponible) + ')';
      if (idx < deptsProximosNotificar.length - 1) alertMsg += '\n\n───────────────────────\n\n';
    });
  }
  alertMsg += '\n\n───────────────────────\n👨‍💻 <i>Sistema desarrollado por: Ing. Vladimir Marcano</i>';
  return [{ json: { sendNotification: true, executionType: 'alert_check', message: alertMsg, gastoTotalGlobal: gastoTotalGlobalMes, alertasCount: totalAlertasANotificar } }];
} else {
  let messageHtml = '';
  if (executionType === 'weekly_report' || !esMesActualEnEjecucion) {
    messageHtml += '📊 <b>' + tituloCabecera + ' - ROYAL EXPRESS C.A.</b>\n\n📅 ' + labelPeriodo + '\n\n';
    deptsResumen.forEach(function(d, index) {
      messageHtml += d.emoji + '<b>' + d.departamento + '</b>\n• Gasto de la Semana: ' + formatUSD(d.gastoPeriodo) + '\n\n• Acumulado del mes: ' + formatUSD(d.gastoMensual) + '\n\n';
      if (index < deptsResumen.length - 1) messageHtml += '───────────────────────\n\n';
    });
    messageHtml += '───────────────────────\n💼 <b>PRESUPUESTO MENSUAL GLOBAL</b>\n\nTotal Ejecutado (Mes) ' + formatUSD(gastoTotalGlobalMes);
  } else {
    messageHtml += '📊 <b>' + tituloCabecera + ' - ROYAL EXPRESS C.A.</b>\n📅 Mes: ' + labelPeriodo + '\n\n';
    deptsResumen.forEach(function(d, index) {
      messageHtml += d.emoji + '<b>' + d.departamento + '</b>\n• Semana en curso: ' + formatUSD(d.gastoPeriodo) + ' (Lim: ' + formatUSD(d.limiteSemanalAprox) + ')\n📉 Avance de la semana: [<code>' + d.barraPeriodo + '</code>] ' + Math.round(d.porcentajePeriodo) + '%\n\n• Acumulado al mes: ' + formatUSD(d.gastoMensual) + ' (Lim: ' + formatUSD(d.limiteMensual) + ')\n📈 Avance mensual: [<code>' + d.barraMensual + '</code>] ' + Math.round(d.porcentajeMensual) + '%\n';
      if (index < deptsResumen.length - 1) messageHtml += '───────────────────────\n';
    });
    const pctMensualGlobal = (gastoTotalGlobalMes / PRESUPUESTO_MENSUAL_GLOBAL) * 100;
    const barraMensualGlobal = generarBarraProgreso(pctMensualGlobal);
    const saldoDisponible = PRESUPUESTO_MENSUAL_GLOBAL - gastoTotalGlobalMes;
    messageHtml += '\n━━━━━━━━━━━━━━━━━━━━━━━\n💼 <b>PRESUPUESTO MENSUAL GLOBAL</b>\nPresupuesto total: ' + formatUSD(PRESUPUESTO_MENSUAL_GLOBAL) + '\n\nEjecutado hasta la fecha: ' + formatUSD(gastoTotalGlobalMes) + '\n📈 Avance Mensual: [<code>' + barraMensualGlobal + '</code>] ' + Math.round(pctMensualGlobal) + '%\n\n💰 Saldo disponible: ' + formatUSD(saldoDisponible);
  }
  messageHtml += '\n\n───────────────────────\n👨‍💻 <i>Sistema desarrollado por: Ing. Vladimir Marcano</i>';
  return [{ json: { sendNotification: true, executionType: executionType, message: messageHtml, gastoTotalGlobal: gastoTotalGlobalMes, alertasCount: 0, deptsResumen: deptsResumen } }];
}

