function obtenerCampo(row, aliasList) {
  if (!row || typeof row !== 'object') return undefined;
  const keys = Object.keys(row);
  for (const key of keys) {
    const keyLimpia = key.trim().toUpperCase();
    for (const alias of aliasList) {
      if (keyLimpia === alias.toUpperCase()) {
        const val = row[key];
        if (val !== undefined && val !== null && val !== '') return val;
      }
    }
  }
  for (const key of keys) {
    const keyLimpia = key.trim().toUpperCase();
    for (const alias of aliasList) {
      if (alias.length > 2 && keyLimpia.includes(alias.toUpperCase())) {
        const val = row[key];
        if (val !== undefined && val !== null && val !== '') return val;
      }
    }
  }
  return undefined;
}

// =========================================================
// BLINDAJE ANTI-BALAS: DETECCIÓN DINÁMICA DE COLUMNAS
// -----------------------------------------------------------
// Los archivos ENERO-ABRIL usan 8 columnas (TIPO DE GASTO en la
// columna D, "$" en la columna G) y los archivos MAYO en adelante
// usan 11 columnas (TIPO DE GASTO en la columna G, "$" en la
// columna J). En vez de depender de la posición fija de cada
// columna, buscamos la fila real de encabezados dentro del propio
// Excel (la que contiene literalmente "FECHA", "TIPO DE GASTO" y
// "$") y construimos el mapa de columnas a partir de ella. Así el
// flujo funciona sin importar el mes, el orden de columnas o si en
// el futuro se agregan/quitan columnas nuevas. Si por algún motivo
// no se logra detectar el encabezado, se usan los alias fijos de
// siempre como respaldo (doble seguro).
// =========================================================
function detectarMapaColumnas(items) {
  const objetivos = {
    FECHA: ['FECHA', 'FECHA GASTO', 'FECHA DE GASTO'],
    TIPO: ['TIPO DE GASTO', 'TIPO GASTO'],
    MONTO: ['$']
  };
  for (const item of items) {
    const row = item.json || {};
    const keys = Object.keys(row);
    const mapaTemp = {};
    for (const key of keys) {
      const val = row[key];
      if (val === undefined || val === null || val === '') continue;
      const valLimpio = String(val).trim().toUpperCase();
      for (const campo of Object.keys(objetivos)) {
        if (mapaTemp[campo]) continue;
        if (objetivos[campo].indexOf(valLimpio) !== -1) {
          mapaTemp[campo] = key;
        }
      }
    }
    if (mapaTemp.FECHA && mapaTemp.TIPO && mapaTemp.MONTO) {
      return mapaTemp;
    }
  }
  return null;
}

function leerCampo(row, mapaColumnas, campo, aliasEstatico) {
  if (mapaColumnas && mapaColumnas[campo]) {
    const val = row[mapaColumnas[campo]];
    if (val !== undefined && val !== null && val !== '') return val;
  }
  // Respaldo: alias fijos originales (por si el encabezado no se detecta)
  return obtenerCampo(row, aliasEstatico);
}

function extraerMonto(valor) {
  if (valor === undefined || valor === null || valor === '') return 0;
  if (typeof valor === 'number') return isNaN(valor) ? 0 : valor;
  let str = String(valor).trim();
  if (!str) return 0;
  let esNegativo = false;
  if (str.startsWith('(') && str.endsWith(')')) {
    esNegativo = true;
    str = str.slice(1, -1);
  }
  str = str.replace(/[^0-9.,-]/g, '');
  if (!str) return 0;
  const lastDot = str.lastIndexOf('.');
  const lastComma = str.lastIndexOf(',');
  if (lastDot !== -1 && lastComma !== -1) {
    if (lastComma > lastDot) {
      str = str.replace(/\./g, '').replace(',', '.');
    } else {
      str = str.replace(/,/g, '');
    }
  } else if (lastComma !== -1) {
    str = str.replace(',', '.');
  }
  let num = parseFloat(str);
  if (isNaN(num)) return 0;
  return esNegativo ? -num : num;
}

function parseFecha(valor) {
  if (!valor) return null;
  if (valor instanceof Date) return isNaN(valor.getTime()) ? null : valor;
  if (typeof valor === 'number') {
    if (valor > 30000 && valor < 60000) {
      const dateMs = (valor - 25569) * 86400 * 1000;
      const temp = new Date(dateMs);
      return new Date(temp.getUTCFullYear(), temp.getUTCMonth(), temp.getUTCDate());
    }
    return null;
  }
  const str = String(valor).trim();
  if (!str) return null;
  const matchDMY = str.match(/^(\d{1,2})[/-](\d{1,2})[/-](\d{2,4})/);
  if (matchDMY) {
    let day = parseInt(matchDMY[1], 10);
    let month = parseInt(matchDMY[2], 10) - 1;
    let year = parseInt(matchDMY[3], 10);
    if (year < 100) year += 2000;
    if (day > 31 && year <= 31) return new Date(day, month, year);
    return new Date(year, month, day);
  }
  const parsed = new Date(str);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function normalizarCodigo(texto) {
  if (!texto) return null;
  const str = String(texto).trim().toUpperCase();
  if (str === 'G1') return 'GC1';
  if (str === 'G2') return 'GC2';
  const codigosOficiales = DEPARTAMENTOS_CONFIG.map(d => d.codigo);
  if (codigosOficiales.includes(str)) return str;
  return null;
}


const ALIAS_FECHA = ['FECHA', 'FECHA GASTO', 'FECHA DE GASTO', 'DIA', 'DÍA', '__EMPTY_1', 'B'];
const ALIAS_TIPO  = ['TIPO DE GASTO', 'TIPO GASTO', 'CODIGO', 'CÓDIGO', 'DEPTO', 'DEPARTAMENTO', 'TIPO', '__EMPTY_6', '__EMPTY_3', 'G'];
const ALIAS_MONTO = ['$', 'MONTO', 'MONTO ($)', 'IMPORTE', 'GASTO', 'VALOR', 'TOTAL', '__EMPTY_9', '__EMPTY_6', 'J'];

// =========================================================
// MAPA DE COLUMNAS POR ARCHIVO DE ORIGEN (fix del "tope" anual)
// -----------------------------------------------------------
// Antes se calculaba UN solo mapa de columnas (detectarMapaColumnas)
// para TODAS las filas de los archivos mensuales ya combinadas,
// usando como referencia la PRIMERA fila de encabezado encontrada.
// Como Enero-Abril usa 8 columnas y Mayo en adelante usa 11, ese
// mapa "global" solo era válido para el archivo que lo originó: el
// resto de los meses con estructura distinta quedaba en $0.00 sin
// lanzar ningún error. Ahora se agrupan las filas por archivo de
// origen usando la etiqueta EXPLÍCITA "_mesOrigenArchivo" que pone
// el nodo "Etiquetar Mes Anual" (con pairedItem solo como
// respaldo por compatibilidad) y se calcula un mapa de columnas
// INDEPENDIENTE por cada archivo.
// =========================================================
function origenDeItem(item, idxFallback) {
  if (item && item.json && item.json._mesOrigenArchivo) {
    return item.json._mesOrigenArchivo;
  }
  try {
    const pi = item.pairedItem;
    if (pi === undefined || pi === null) return idxFallback;
    if (Array.isArray(pi)) {
      return (pi[0] && typeof pi[0].item === 'number') ? pi[0].item : idxFallback;
    }
    if (typeof pi.item === 'number') return pi.item;
  } catch (e) {}
  return idxFallback;
}

const gruposPorArchivo = new Map();
inputItems.forEach((item, idx) => {
  const origen = origenDeItem(item, idx);
  if (!gruposPorArchivo.has(origen)) gruposPorArchivo.set(origen, []);
  gruposPorArchivo.get(origen).push(item);
});

const NOMBRES_MESES = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];

// =========================================================
// AÑO A CONSOLIDAR: se usa el año actual del sistema, así el
// Informe Anual siempre corresponde al año en curso sin importar
// cuántos archivos mensuales existan todavía.
// =========================================================
const hoy = new Date();
const anioActual = hoy.getFullYear();

const matriz = {};
DEPARTAMENTOS_CONFIG.forEach(dpt => { matriz[dpt.codigo] = new Array(12).fill(0); });

let gastoTotalAnio = 0;
const mesesConDatosSet = new Set();

for (const [, filasDelArchivo] of gruposPorArchivo) {
  // Mapa de columnas calculado SOLO con las filas de este archivo.
  const mapaColumnasArchivo = detectarMapaColumnas(filasDelArchivo);

  for (const item of filasDelArchivo) {
    const row = item.json || {};
    const codigo = normalizarCodigo(leerCampo(row, mapaColumnasArchivo, 'TIPO', ALIAS_TIPO));
    if (!codigo) continue;
    const monto = extraerMonto(leerCampo(row, mapaColumnasArchivo, 'MONTO', ALIAS_MONTO));
    if (monto === 0) continue;
    const fechaGasto = parseFecha(leerCampo(row, mapaColumnasArchivo, 'FECHA', ALIAS_FECHA));
    if (!fechaGasto) continue;
    // Consolidar SOLO los gastos del año actual, sin importar de qué
    // archivo mensual provenga la fila (la fecha real de cada gasto
    // es la que decide a qué mes pertenece).
    if (fechaGasto.getFullYear() !== anioActual) continue;

    const mesIdx = fechaGasto.getMonth(); // 0 = Enero ... 11 = Diciembre
    matriz[codigo][mesIdx] += monto;
    gastoTotalAnio += monto;
    mesesConDatosSet.add(mesIdx);
  }
}

const categorias = DEPARTAMENTOS_CONFIG.map(dept => {
  const { codigo, nombre, emoji, limiteMensual } = dept;
  const porMes = matriz[codigo].map(v => Math.round(v * 100) / 100);
  const total = porMes.reduce((a, b) => a + b, 0);
  const pctTotal = gastoTotalAnio > 0 ? (total / gastoTotalAnio) * 100 : 0;
  const mesesConGastos = porMes.filter(v => v > 0).length;
  const promedioMensual = mesesConGastos > 0 ? total / mesesConGastos : 0;
  const limiteAnual = limiteMensual * 12;
  const pctLimiteAnual = limiteAnual > 0 ? (total / limiteAnual) * 100 : 0;
  return {
    codigo, nombre, emoji, color: COLORES_CATEGORIA[codigo] || '#94a3b8',
    limiteMensual,
    limiteAnual: Math.round(limiteAnual * 100) / 100,
    porMes,
    total: Math.round(total * 100) / 100,
    pctTotal: Math.round(pctTotal * 10) / 10,
    pctLimiteAnual: Math.round(pctLimiteAnual * 10) / 10,
    promedioMensual: Math.round(promedioMensual * 100) / 100,
    mesesConGastos,
    totalMeses: 12
  };
});

// =========================================================
// SE LISTAN OBLIGATORIAMENTE LOS 12 MESES DEL AÑO. Los meses que
// aún no tienen archivo/datos (por ejemplo, de septiembre en
// adelante) quedan automáticamente en $0.00 porque la matriz se
// inicializa en 0 y nunca se les suma nada. No se genera ningún
// error por la ausencia de datos.
// =========================================================
const meses = NOMBRES_MESES.map((nombreMes, i) => {
  let totalMes = 0;
  const porCategoria = {};
  DEPARTAMENTOS_CONFIG.forEach(dpt => {
    const v = matriz[dpt.codigo][i];
    porCategoria[dpt.codigo] = Math.round(v * 100) / 100;
    totalMes += v;
  });
  return {
    indice: i + 1,
    nombre: nombreMes,
    porCategoria: porCategoria,
    totalMes: Math.round(totalMes * 100) / 100,
    pctAnio: gastoTotalAnio > 0 ? Math.round((totalMes / gastoTotalAnio) * 1000) / 10 : 0,
    tieneDatos: totalMes > 0
  };
});

const hayDatos = gastoTotalAnio > 0;
const categoriasConGastos = categorias.filter(c => c.total > 0).length;
const presupuestoAnual = PRESUPUESTO_MENSUAL_GLOBAL * 12;
const saldoDisponibleAnual = Math.round((presupuestoAnual - gastoTotalAnio) * 100) / 100;
const porcentajeAnual = presupuestoAnual > 0 ? Math.round((gastoTotalAnio / presupuestoAnual) * 1000) / 10 : 0;

// =========================================================
// DIAGNÓSTICO: qué archivos se agruparon y cuántas filas aportó
// cada uno. Visible en el output de este nodo dentro de la
// ejecución de n8n para verificar de un vistazo si TODOS los
// archivos descargados llegaron aquí correctamente separados.
// =========================================================
const diagnosticoArchivos = Array.from(gruposPorArchivo.entries()).map(([origen, filas]) => ({
  origen: origen,
  filasExtraidas: filas.length
}));

let chatId = null;
try { chatId = $('Telegram Trigger').first().json.message.chat.id; } catch (e) {}

return [{
  json: {
    chatId: chatId,
    anio: anioActual,
    diagnosticoArchivos: diagnosticoArchivos,
    mesesConDatos: mesesConDatosSet.size,
    gastoTotalAnio: Math.round(gastoTotalAnio * 100) / 100,
    presupuestoAnual: Math.round(presupuestoAnual * 100) / 100,
    saldoDisponibleAnual: saldoDisponibleAnual,
    porcentajeAnual: porcentajeAnual,
    categoriasConGastos: categoriasConGastos,
    totalCategorias: DEPARTAMENTOS_CONFIG.length,
    categorias: categorias,
    meses: meses,
    hayDatos: hayDatos,
    fechaGeneracion: new Date().toLocaleString('es-VE', { dateStyle: 'long', timeStyle: 'short' })
  }
}];

