const d = $input.first().json;

if (!d.hayDatos || d.gastoTotalAnio === 0) {
  const mensaje = '📋 <b>INFORME ANUAL DE GASTOS - ROYAL EXPRESS C.A - ' + d.anio + '</b>\n\n' +
                  '⚠️ <b>NO HAY DATOS REGISTRADOS</b>\n\n' +
