function formatUSD(val) {
  var num = Number(val) || 0;
  var rounded = Math.round(num * 100) / 100;
  var negativo = rounded < 0;
  var abs = Math.abs(rounded);
  var parts = abs.toFixed(2).split('.');
  var integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return (negativo ? '-' : '') + 'USD ' + integerPart + ',' + parts[1];
}

function formatNum(val) {
  var num = Number(val) || 0;
  var rounded = Math.round(num * 100) / 100;
  var parts = rounded.toFixed(2).split('.');
  var integerPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  return integerPart + ',' + parts[1];
}

function esc(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function colorEstado(pct) {
  if (pct >= 100) return { color: '#f87171', bg: 'rgba(248,113,113,0.12)', label: 'EXCEDIDO' };
  if (pct >= 80)  return { color: '#facc15', bg: 'rgba(250,204,21,0.12)', label: 'ATENCIÓN' };
  return { color: '#4ade80', bg: 'rgba(74,222,128,0.12)', label: 'EN CONTROL' };
}

function nivelBadge(nivel) {
  if (nivel >= 40) return { color: '#f87171', bg: 'rgba(248,113,113,0.15)', label: 'ALTO' };
  if (nivel >= 15) return { color: '#facc15', bg: 'rgba(250,204,21,0.15)', label: 'MEDIO' };
  return { color: '#4ade80', bg: 'rgba(74,222,128,0.15)', label: 'BAJO' };
}

var MESES_ABREV = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
var catsConGasto = d.categorias ? d.categorias.filter(function(c) { return c.total > 0; }) : [];

function graficaEvolucionAnual() {
  var W = 900, H = 380;
  var padL = 64, padR = 20, padT = 20, padB = 44;
  var plotW = W - padL - padR;
  var plotH = H - padT - padB;
  var n = 12;

  var maxY = 0;
  catsConGasto.forEach(function(c) { c.porMes.forEach(function(v) { if (v > maxY) maxY = v; }); });
  if (maxY <= 0) maxY = 1;
  var step = Math.pow(10, Math.floor(Math.log10(maxY)));
  maxY = Math.ceil(maxY / step) * step;

  var xFor = function(i) { return padL + (n <= 1 ? plotW / 2 : (plotW * i) / (n - 1)); };
  var yFor = function(v) { return padT + plotH - (v / maxY) * plotH; };

  var grid = '';
  var lines = 4;
  for (var g = 0; g <= lines; g++) {
    var val = (maxY / lines) * g;
    var y = yFor(val);
    grid += '<line x1="' + padL + '" y1="' + y.toFixed(1) + '" x2="' + (W - padR) + '" y2="' + y.toFixed(1) + '" stroke="#23304f" stroke-width="1"/>';
    grid += '<text x="' + (padL - 8) + '" y="' + (y + 4).toFixed(1) + '" text-anchor="end" fill="#93a0c2" font-size="11">' + Math.round(val).toLocaleString('es-ES') + '</text>';
  }

  var xlabels = '';
  for (var i = 0; i < n; i++) {
    xlabels += '<text x="' + xFor(i).toFixed(1) + '" y="' + (H - padB + 22) + '" text-anchor="middle" fill="#93a0c2" font-size="11">' + MESES_ABREV[i] + '</text>';
  }

  var paths = '', dots = '';
  catsConGasto.forEach(function(c) {
    var pts = c.porMes.map(function(v, i) { return xFor(i).toFixed(1) + ',' + yFor(v).toFixed(1); });
    paths += '<polyline points="' + pts.join(' ') + '" fill="none" stroke="' + c.color + '" stroke-width="2.5" stroke-linejoin="round" stroke-linecap="round"/>';
    c.porMes.forEach(function(v, i) {
      dots += '<circle cx="' + xFor(i).toFixed(1) + '" cy="' + yFor(v).toFixed(1) + '" r="3" fill="' + c.color + '"/>';
    });
  });

  return '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg" role="img">' + grid + paths + dots + xlabels + '</svg>';
}

function graficaDistribucionAnual() {
  var size = 260, cx = size / 2, cy = size / 2, r = 100, rInner = 60;
  var total = catsConGasto.reduce(function(a, c) { return a + c.total; }, 0) || 1;

  var ang = -Math.PI / 2, segs = '';
  catsConGasto.forEach(function(c) {
    var frac = c.total / total;
    var a0 = ang, a1 = ang + frac * 2 * Math.PI;
    ang = a1;
    var large = (a1 - a0) > Math.PI ? 1 : 0;
    var x0 = cx + r * Math.cos(a0), y0 = cy + r * Math.sin(a0);
    var x1 = cx + r * Math.cos(a1), y1 = cy + r * Math.sin(a1);
    var xi1 = cx + rInner * Math.cos(a1), yi1 = cy + rInner * Math.sin(a1);
    var xi0 = cx + rInner * Math.cos(a0), yi0 = cy + rInner * Math.sin(a0);
    segs += '<path d="M ' + x0.toFixed(1) + ' ' + y0.toFixed(1) + ' A ' + r + ' ' + r + ' 0 ' + large + ' 1 ' + x1.toFixed(1) + ' ' + y1.toFixed(1) + ' L ' + xi1.toFixed(1) + ' ' + yi1.toFixed(1) + ' A ' + rInner + ' ' + rInner + ' 0 ' + large + ' 0 ' + xi0.toFixed(1) + ' ' + yi0.toFixed(1) + ' Z" fill="' + c.color + '"/>';
  });

  return '<svg viewBox="0 0 ' + size + ' ' + size + '" width="240" height="240" preserveAspectRatio="xMidYMid meet" xmlns="http://www.w3.org/2000/svg" role="img">' + segs + '<text x="' + cx + '" y="' + (cy - 6) + '" text-anchor="middle" fill="#93a0c2" font-size="12">Total año</text><text x="' + cx + '" y="' + (cy + 14) + '" text-anchor="middle" fill="#e5e9f5" font-size="14" font-weight="700">' + formatUSD(d.gastoTotalAnio).replace('USD ', '') + '</text></svg>';
}

function tablaDetalleAnual() {
  var cols = d.categorias || [];
  var head = '<th class="sticky-col">Mes</th>';
  cols.forEach(function(c) { head += '<th>' + esc(c.nombre) + '</th>'; });
  head += '<th>Total Mes</th><th>% del Año</th>';

  var body = '';
  (d.meses || []).forEach(function(mes) {
    var row = '<td class="sticky-col">' + esc(mes.nombre) + '</td>';
    cols.forEach(function(c) { row += '<td>' + formatUSD(mes.porCategoria[c.codigo] || 0) + '</td>'; });
    row += '<td class="strong">' + formatUSD(mes.totalMes) + '</td><td>' + mes.pctAnio + '%</td>';
    body += '<tr' + (mes.tieneDatos ? '' : ' class="sin-datos"') + '>' + row + '</tr>';
  });

  var totalRow = '<td class="sticky-col strong">TOTAL AÑO</td>';
  cols.forEach(function(c) { totalRow += '<td class="strong">' + formatUSD(c.total) + '</td>'; });
  totalRow += '<td class="strong">' + formatUSD(d.gastoTotalAnio) + '</td><td class="strong">100%</td>';
  body += '<tr class="total-row">' + totalRow + '</tr>';

  return '<div class="table-scroll"><table><thead><tr>' + head + '</tr></thead><tbody>' + body + '</tbody></table></div>';
}

function resumenCategoriasAnual() {
  return (d.categorias || []).map(function(c) {
    var b = nivelBadge(c.pctTotal);
    return '<div class="card"><div class="card-head"><span class="card-title">' + esc(c.emoji) + ' ' + esc(c.nombre) + '</span></div><div class="card-amount">' + formatUSD(c.total) + '</div><div class="card-sub">' + c.pctTotal + '% del gasto total<span class="badge" style="color:' + b.color + ';background:' + b.bg + ';">' + b.label + '</span></div><div class="card-line">Límite anual: ' + formatUSD(c.limiteAnual) + ' (' + c.pctLimiteAnual + '% usado)</div><div class="card-line">Promedio mensual: ' + formatUSD(c.promedioMensual) + '</div><div class="card-line">Meses con gastos: ' + c.mesesConGastos + ' de 12</div></div>';
  }).join('\n');
}

var estadoGlobal = colorEstado(d.porcentajeAnual);

var html = '<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Informe Anual — ' + d.anio + '</title>\n<style>\n  :root { --bg: #0f172a; --bg-card: #161f36; --border: #23304f; --text-primary: #e5e9f5; --text-secondary: #93a0c2; --accent: #38bdf8; }\n  * { box-sizing: border-box; margin: 0; padding: 0; }\n  body { background: var(--bg); color: var(--text-primary); font-family: \'Segoe UI\', -apple-system, BlinkMacSystemFont, Roboto, Arial, sans-serif; padding: 28px 16px 60px; }\n  .container { max-width: 980px; margin: 0 auto; }\n  header { text-align: center; margin-bottom: 28px; padding-bottom: 20px; border-bottom: 1px solid var(--border); }\n  header h1 { font-size: 22px; font-weight: 700; }\n  header p { color: var(--text-secondary); font-size: 13px; margin-top: 6px; }\n  .author-badge { display: inline-block; margin-top: 8px; font-size: 11px; color: var(--accent); font-family: monospace; letter-spacing: 0.5px; }\n  .summary-strip { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 12px; margin: 24px 0 40px; }\n  .summary-box { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 16px; }\n  .summary-box .label { font-size: 12px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.4px; }\n  .summary-box .val { font-size: 20px; font-weight: 700; margin-top: 6px; }\n  .summary-box .hint { font-size: 11px; color: var(--text-secondary); margin-top: 4px; }\n  section { margin-bottom: 40px; }\n  section > h2 { font-size: 17px; font-weight: 700; margin-bottom: 16px; }\n  .panel { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 18px; }\n  .chart-box { width: 100%; overflow: hidden; }\n  .chart-box.donut { display: flex; justify-content: center; }\n  .legend { display: flex; flex-wrap: wrap; gap: 10px 16px; margin-top: 14px; justify-content: center; }\n  .leg-item { display: inline-flex; align-items: center; font-size: 12px; color: var(--text-secondary); }\n  .leg-dot { width: 11px; height: 11px; border-radius: 50%; margin-right: 6px; display: inline-block; }\n  .dist-wrap { display: flex; flex-wrap: wrap; gap: 24px; align-items: center; justify-content: center; }\n  .dist-legend { flex: 1; min-width: 240px; }\n  .dist-item { display: flex; align-items: center; padding: 6px 0; border-bottom: 1px solid var(--border); font-size: 13px; }\n  .dist-item:last-child { border-bottom: none; }\n  .dist-name { flex: 1; }\n  .dist-val { font-weight: 700; }\n  .table-scroll { overflow-x: auto; -webkit-overflow-scrolling: touch; border: 1px solid var(--border); border-radius: 12px; }\n  table { border-collapse: collapse; width: 100%; min-width: 720px; font-size: 12.5px; }\n  th, td { padding: 10px 12px; text-align: right; white-space: nowrap; border-bottom: 1px solid var(--border); }\n  th { background: #101a30; color: var(--text-secondary); font-weight: 600; text-transform: uppercase; font-size: 11px; }\n  th:first-child, td:first-child { text-align: left; }\n  .sticky-col { position: sticky; left: 0; background: var(--bg-card); }\n  th.sticky-col { background: #101a30; }\n  td.strong { font-weight: 700; color: var(--text-primary); }\n  tr.total-row td { background: #101a30; font-weight: 700; border-top: 2px solid #38bdf8; }\n  tr.sin-datos td { color: var(--text-secondary); opacity: 0.55; }\n  .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr)); gap: 14px; }\n  .card { background: var(--bg-card); border: 1px solid var(--border); border-radius: 12px; padding: 16px; }\n  .card-head { margin-bottom: 8px; }\n  .card-title { font-size: 14px; font-weight: 600; }\n  .card-amount { font-size: 20px; font-weight: 700; }\n  .card-sub { font-size: 12px; color: var(--text-secondary); margin: 6px 0 10px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }\n  .badge { font-size: 10px; font-weight: 700; padding: 3px 8px; border-radius: 999px; }\n  .card-line { font-size: 12px; color: var(--text-secondary); margin-top: 3px; }\n  footer { text-align: center; color: var(--text-secondary); font-size: 12px; margin-top: 36px; line-height: 1.6; }\n  footer strong { color: var(--accent); }\n</style>\n</head>\n<body>\n<div class=\"container\">\n<header>\n<h1>INFORME ANUAL DE GASTOS — ROYAL EXPRESS C.A — ' + d.anio + '</h1>\n<p>Consolidado de los ' + d.mesesConDatos + ' mes(es) con información disponible · Generado el ' + esc(d.fechaGeneracion) + '</p>\n<span class=\"author-badge\">ELABORADO POR: <strong>ING. VLADIMIR MARCANO</strong></span>\n</header>\n<div class=\"summary-strip\">\n<div class=\"summary-box\"><div class=\"label\">Gasto Total del Año</div><div class=\"val\" style=\"color:' + estadoGlobal.color + ';\">' + formatUSD(d.gastoTotalAnio) + '</div></div>\n<div class=\"summary-box\"><div class=\"label\">Categorías con Gastos</div><div class=\"val\">' + d.categoriasConGastos + '</div><div class=\"hint\">de ' + d.totalCategorias + ' totales</div></div>\n</div>\n<section><h2>Evolución Mensual por Categoría</h2><div class=\"panel\"><div class=\"chart-box\">' + graficaEvolucionAnual() + '</div><div class=\"legend\">' + catsConGasto.map(function(c) { return '<span class=\"leg-item\"><span class=\"leg-dot\" style=\"background:' + c.color + ';\"></span>' + esc(c.nombre) + '</span>'; }).join('') + '</div></div></section>\n<section><h2>Distribución de Gastos por Categoría</h2><div class=\"panel\"><div class=\"dist-wrap\"><div class=\"chart-box donut\">' + graficaDistribucionAnual() + '</div><div class=\"dist-legend\">' + catsConGasto.slice().sort(function(a, b) { return b.total - a.total; }).map(function(c) { return '<div class=\"dist-item\"><span class=\"leg-dot\" style=\"background:' + c.color + ';\"></span><span class=\"dist-name\">' + esc(c.emoji) + ' ' + esc(c.nombre) + '</span><span class=\"dist-val\">' + c.pctTotal + '%</span></div>'; }).join('') + '</div></div></div></section>\n<section><h2>Detalle por Mes (12 meses)</h2>' + tablaDetalleAnual() + '</section>\n<section><h2>Resumen por Categoría</h2><div class=\"grid\">' + resumenCategoriasAnual() + '</div></section>\n<footer>' +
'<p>Documento generado automáticamente · Royal Express C.A. · Informe Anual ' + d.anio + '</p>' +
'<p style="font-size: 11px; margin-top: 4px; font-family: monospace;">SISTEMA AUTOMATIZADO ELABORADO Y PROGRAMADO POR: <strong>ING. VLADIMIR MARCANO</strong></p>' +
'</footer>\n</div>\n</body>\n</html>';

var fileName = 'INFORME ANUAL DE GASTOS-ROYAL EXPRESS C.A- ' + d.anio + '.html';
var caption = 'INFORME ANUAL DE GASTOS - ROYAL EXPRESS C.A - ' + d.anio;

return [{
  json: {
    htmlContent: html,
    fileName: fileName,
    caption: caption,
    chatId: d.chatId,
    hayDatos: d.hayDatos,
    esMensajeTexto: false
  }
}];

// =========================================================
// Etiqueta cada fila extraída con el mes/archivo de origen de
// forma EXPLÍCITA. "Loop Archivos Anuales" procesa un solo
// archivo por iteración (batchSize: 1), así que en este punto solo
// puede haber UN archivo activo: se lee directamente del propio
// nodo de loop en vez de depender de pairedItem. Este campo queda
// visible en cada fila dentro de la ejecución de n8n, así que
// también sirve como diagnóstico.
// =========================================================
let mesOrigen = null;
let nombreArchivoOrigen = null;

try {
  const loopItem = $('Loop Archivos Anuales').first().json;
  mesOrigen = loopItem.mesNombre || null;
  nombreArchivoOrigen = loopItem.name || null;
} catch (e) {}

return $input.all().map(item => ({
  json: {
    ...item.json,
    _mesOrigenArchivo: mesOrigen,
    _nombreArchivoOrigen: nombreArchivoOrigen
  }
}));

// ======================================================
// ROYAL EXPRESS C.A. - PREPARAR PARÁMETROS GASTOS (2 PEQUEÑOS ARRIBA + 3 GRANDES APILADOS)
// ======================================================
var inputItems = $input.all();
var triggerJson = {};
try { triggerJson = $('Telegram Trigger').first().json; } catch(e) {}

var item = (triggerJson && (triggerJson.message || triggerJson.callback_query)) ? triggerJson : (inputItems.length ? inputItems[0].json : {});

var textoMensaje = '';
var chatId = '-5235938481';
var fromName = 'Usuario';

if (item.callback_query) {
  textoMensaje = item.callback_query.data ? String(item.callback_query.data).trim() : '';
  chatId = (item.callback_query.message && item.callback_query.message.chat) ? String(item.callback_query.message.chat.id) : chatId;
  fromName = (item.callback_query.from && (item.callback_query.from.first_name || item.callback_query.from.username)) || 'Usuario';
} else if (item.message) {
  textoMensaje = item.message.text ? String(item.message.text).trim() : '';
  chatId = (item.message.chat) ? String(item.message.chat.id) : chatId;
  fromName = (item.from && (item.from.first_name || item.from.username)) || 'Usuario';
}

var textoLower = textoMensaje.toLowerCase();
var sub = 'menu_principal';

if (textoLower === '/menu_meses') sub = 'menu_meses';
else if (textoLower === '/menu_semanas') sub = 'menu_semanas';

var text = '';
var reply_markup = null;

if (sub === 'menu_principal') {
  text = '🧾 <b>ROYAL EXPRESS C.A. — MONITOREO DE GASTOS DEPARTAMENTALES</b>\n\nHola <b>' + fromName + '</b>, selecciona el reporte que deseas consultar:';
  reply_markup = {
    inline_keyboard: [
      [
        { text: '📊 Reporte Diario', callback_data: '/reporte' },
        { text: '📆 Seleccionar Semana 🔽', callback_data: '/menu_semanas' }
      ],
      [
        { text: '🗓️ Reporte de Seguimiento Mes Actual (Gráfica)', callback_data: '/graficas_mes_actual' }
      ],
      [
        { text: '🗓️ Informe Mensual de Gastos (Seleccionar Mes) 🔽', callback_data: '/menu_meses' }
      ],
      [
        { text: '📈 Informe Anual de gastos 2026 (Gráfica)', callback_data: '/anual' }
      ]
    ]
  };
} else if (sub === 'menu_meses') {
  text = '🗓️ <b>SELECCIONA EL MES DE GASTOS A CONSULTAR:</b>';
  reply_markup = {
    inline_keyboard: [
      [{ text: 'Enero (Gráfica)', callback_data: '/mes_1' }, { text: 'Febrero (Gráfica)', callback_data: '/mes_2' }, { text: 'Marzo (Gráfica)', callback_data: '/mes_3' }],
      [{ text: 'Abril (Gráfica)', callback_data: '/mes_4' }, { text: 'Mayo (Gráfica)', callback_data: '/mes_5' }, { text: 'Junio (Gráfica)', callback_data: '/mes_6' }],
      [{ text: 'Julio (Gráfica)', callback_data: '/mes_7' }, { text: 'Agosto (Gráfica)', callback_data: '/mes_8' }, { text: 'Septiembre (Gráfica)', callback_data: '/mes_9' }],
      [{ text: 'Octubre (Gráfica)', callback_data: '/mes_10' }, { text: 'Noviembre (Gráfica)', callback_data: '/mes_11' }, { text: 'Diciembre (Gráfica)', callback_data: '/mes_12' }],
      [{ text: '⬅️ Volver al Menú Principal', callback_data: '/menu_principal' }]
    ]
  };
} else if (sub === 'menu_semanas') {
  text = '📆 <b>SELECCIONA LA SEMANA DE GASTOS:</b>';
  reply_markup = {
    inline_keyboard: [
      [{ text: 'Semana 1 (Gráfica)', callback_data: '/semana 1' }, { text: 'Semana 2 (Gráfica)', callback_data: '/semana 2' }],
      [{ text: 'Semana 3 (Gráfica)', callback_data: '/semana 3' }, { text: 'Semana 4 (Gráfica)', callback_data: '/semana 4' }],
      [{ text: '⬅️ Volver al Menú Principal', callback_data: '/menu_principal' }]
    ]
  };
}

return [{
  json: {
    chatId: chatId,
    text: text,
    reply_markup: reply_markup
  }
}];
